    "signs": [
      {
        "x": 15,
        "y": 10,
        "text": "NATIONAL PARK — Lawns, ponds, and the famous fountain. Bug-catching days are a local religion."
      }
    ],
    "npcs": [
      {
        "x": 11,
        "y": 6,
        "name": "PARK KEEPER LOU",
        "art": "ranger",
        "skin": "#e8b888",
        "shirt": "#3a6ac0",
        "pants": "#2a3a4a",
        "hair": "#1a1a1a",
        "dialogue": [
          "Twenty years tending these lawns. The PETALGRIN by the pond are my pension plan.",
          "Trainers rest here between cities. The park insists on it."
        ]
      },
      {
        "x": 17,
        "y": 13,
        "name": "BUG MANIAC TESS",
        "art": "lass",
        "skin": "#c89878",
        "shirt": "#2a7a6a",
        "pants": "#3a3a4a",
        "hair": "#7a4a1a",
        "dialogue": [
          "Contest Tuesdays! The park judges have SEEN things.",
          "A DARNLET at the fountain at noon is the park's whole personality."
        ]
      },
      {
        "x": 7,
        "y": 10,
        "name": "ELDER PRAN",
        "art": "elder",
        "skin": "#e8b888",
        "shirt": "#b0503c",
        "pants": "#2a2a3a",
        "hair": "#5a3a2a",
        "dialogue": [
          "I walked my first Kin around this fountain. My granddaughter walks hers now.",
          "Parks remember every generation kindly. That is their job."
        ]
      }
    ],
