        "pants": "#4a3a2a",
        "hair": "#2a1a0a",
        "dialogue": [
          "When I grow up I'm surfing to Beacon without the boat. The boatman pretends not to hear.",
          "The Maelstrom Islands sing at night. Everyone here has heard it. Nobody hums it back."
        ]
